def transform(grid):
    """Keep the panel before the full-width separator and recolor its marks."""
    h, w = len(grid), len(grid[0])
    # ARC separator is a uniform, non-background row or column.
    sep_row = next((r for r, row in enumerate(grid)
                    if len(set(row)) == 1 and row[0] != 0), None)
    if sep_row is not None:
        panel = grid[:sep_row]
    else:
        sep_col = next((c for c in range(w)
                        if len({grid[r][c] for r in range(h)}) == 1
                        and grid[0][c] != 0), None)
        if sep_col is None:
            raise ValueError('separator not found')
        panel = [row[:sep_col] for row in grid]
    return [[0 if value == 0 else 2 for value in row] for row in panel]

